/**
 * Issue dependencies ("blocked by" links): recording them, keeping the graph acyclic, gating completion of blocked work and telling assignees when their issue is finally unblocked.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export interface BlockerInput {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
}

/** Raised when a blocked issue is moved to `done` while blockers are still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    public readonly blockerIds: readonly IssueId[],
  ) {
    super(
      `Issue ${issueId} is blocked by ${blockerIds.length} open issue(s): ${blockerIds.join(", ")}`,
    );
    this.name = "IssueBlockedError";
  }
}

const CLOSED_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_STATUSES.includes(status);
}

/** Open means live and neither `done` nor `canceled`. */
function isOpen(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

async function requireIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(await issueRepo.findIssueById(orgId, issueId), "Issue", issueId);
}

/** True when `target` can be reached from `start` by following blocked-by links. */
async function isReachable(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const blockersOf = new Map<IssueId, IssueId[]>();
  for (const link of await dependencyRepo.listDependencies(orgId)) {
    const list = blockersOf.get(link.issueId) ?? [];
    list.push(link.blockerId);
    blockersOf.set(link.issueId, list);
  }

  const seen = new Set<IssueId>([start]);
  const queue: IssueId[] = [start];
  while (queue.length > 0) {
    const current = queue.pop() as IssueId;
    if (current === target) return true;
    for (const next of blockersOf.get(current) ?? []) {
      if (seen.has(next)) continue;
      seen.add(next);
      queue.push(next);
    }
  }
  return false;
}

/** Records "`issueId` is blocked by `blockerId`". Idempotent for existing links. */
export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = await requireIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));
  const blocker = await requireIssue(input.orgId, input.blockerId);

  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  // The new edge issue -> blocker closes a loop iff issue is already
  // reachable from the blocker.
  if (await isReachable(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${issue.id} cannot be blocked by ${blocker.id}: that would create a dependency cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

/** Deletes the link; resolves `false` when there was none. Never notifies. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = await requireIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(input.orgId, issue.id, input.blockerId);
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = await requireIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issue.id);
}

/**
 * The completion gate. Throws `IssueBlockedError` when `issue` still has open
 * blockers; called by the issue service before any change to `done`.
 */
export async function assertNotBlocked(issue: Issue): Promise<void> {
  const open = await dependencyRepo.listOpenBlockers(issue.orgId, issue.id);
  if (open.length > 0) {
    throw new IssueBlockedError(
      issue.id,
      open.map((blocker) => blocker.id),
    );
  }
}

/**
 * Called once `blockerIds` have gone from open to closed: every issue they
 * block that is live, open, assigned and now has no open blocker left hears
 * about it, once.
 */
export async function notifyUnblocked(
  orgId: OrgId,
  actorId: UserId | null,
  blockerIds: readonly IssueId[],
): Promise<void> {
  const handled = new Set<IssueId>();

  for (const blockerId of blockerIds) {
    for (const blocked of await dependencyRepo.listBlockedIssues(orgId, blockerId)) {
      if (handled.has(blocked.id)) continue;
      handled.add(blocked.id);

      if (!isOpen(blocked) || blocked.assigneeId === null) continue;
      if ((await dependencyRepo.listOpenBlockers(orgId, blocked.id)).length > 0) {
        continue;
      }

      await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
        title: "An issue is no longer blocked",
        body: `Issue ${blocked.id} has no open blockers left`,
        href: `/issues/${blocked.id}`,
        actorId,
      });
    }
  }
}

/** Reacts to blockers closing, by status change or by archiving. */
export function registerDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.actorId, [payload.issueId]);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.actorId, [payload.issueId]);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
EOF
